#!/usr/bin/env python3
"""Exact finite Clifford C4 generated by Green sign and reciprocal sewing graph."""
import json
from fractions import Fraction as Q
from pathlib import Path

ROOT=Path(__file__).resolve().parents[3]
W0=json.loads((ROOT/'research/voevodsky/fixtures/prime_two_reciprocal_boundary_sewing_candidate.v1.json').read_text())['sewing_matrix']
W=[[Q(x) for x in r] for r in W0]
n=len(W)
def mm(a,b): return [[sum(a[i][k]*b[k][j] for k in range(len(b))) for j in range(len(b[0]))] for i in range(len(a))]
def tr(a): return [list(r) for r in zip(*a)]
def neg(a): return [[-x for x in r] for r in a]
def eye(n): return [[Q(i==j) for j in range(n)] for i in range(n)]
def zero(n): return [[Q(0) for _ in range(n)] for _ in range(n)]
def block(a,b,c,d): return [a[i]+b[i] for i in range(len(a))]+[c[i]+d[i] for i in range(len(c))]
I=eye(n); Z=zero(n)
S=block(Z,tr(W),W,Z)
J=block(I,Z,Z,neg(I))
F=mm(J,S)
Pp=[[Q(i==j,2)+S[i][j]/2 for j in range(2*n)] for i in range(2*n)]
Pm=[[Q(i==j,2)-S[i][j]/2 for j in range(2*n)] for i in range(2*n)]
checks={
 'W_unitary':mm(tr(W),W)==I,
 'S_involution':mm(S,S)==eye(2*n),
 'J_involution':mm(J,J)==eye(2*n),
 'anticommute':mm(J,S)==neg(mm(S,J)),
 'F_skew':tr(F)==neg(F),
 'F_square_minus_I':mm(F,F)==neg(eye(2*n)),
 'F_fourth_I':mm(mm(F,F),mm(F,F))==eye(2*n),
 'F_maps_chirality':mm(Pp,mm(F,Pp))==zero(2*n) and mm(Pm,mm(F,Pp))==mm(F,Pp),
}
out={'schema':'marici.voevodsky.prime-two-clifford-c4-from-sewing.v1','status':'passed' if all(checks.values()) else 'failed','basis':['incoming:'+x for x in json.loads((ROOT/'research/voevodsky/fixtures/prime_two_radial_boundary_form_candidate.v1.json').read_text())['boundary_basis']]+['outgoing:'+x for x in json.loads((ROOT/'research/voevodsky/fixtures/prime_two_radial_boundary_form_candidate.v1.json').read_text())['boundary_basis']], 'sewing_W':W0,'clifford_quarter_turn_F_C':[[str(x) for x in r] for r in F],'checks':checks,'comparison_status':'No independent analytical Fourier/Tate 8x8 action is exposed in the searched fixtures, so matrix identification remains open.','claim_boundary':'Exact finite algebra on the candidate radial sewing fixture; not an identification with canonical G4 or the completed Evans carrier.'}
p=ROOT/'research/voevodsky/results/prime_two_clifford_c4_from_sewing.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));raise SystemExit(out['status']!='passed')
